archive\"]=\"units.scd\",[\"entry\"]=\"units/XSL0301/XSL0301_unit.bp\",[\"sha256\"]=\"c450b8186498025b31daaf54936cc0ab75b463a23813c7e4d897f8b4bf36fb15\",[\"bytes\"]=28647},[\"sourceScript\"]={[\"archive\"]=\"units.scd\",[\"entry\"]=\"units/XSL0301/XSL0301_script.lua\",[\"sha256\"]=\"e9f482bda409b3ba8d2b608d57cecad6cde7c2692068800fbfc238f2d2491d93\",[\"bytes\"]=13906}}}) do\r\n    if contract.commanders[id] then error('SACU contract owner collision: '..id) end\r\n    contract.commanders[id] = row\r\nend\r\n\r\n_G.SCO_CommanderEnhancementContract = contract", 1)
