	internal static readonly string[] CachePaths = Sections.Select((Section row) => row.Path).Distinct().ToArray();

	private static int Occurrences(string text, string value)
	{
		int num = 0;
		int startIndex = 0;
		while ((startIndex = text.IndexOf(value, startIndex, StringComparison.Ordinal)) >= 0)
		{
			num++;
			startIndex += value.Length;
		}
		return num;
	}

	private static string Digest(string value)
	{
		using SHA256 sHA = SHA256.Create();
		return BitConverter.ToString(sHA.ComputeHash(Encoding.UTF8.GetBytes(value))).Replace("-", "");
	}

	internal static string Patch(string path, string source)
	{
		source = source.Replace("\r\n", "\n");
		foreach (Section item in Sections.Where((Section row) => row.Path == path))
		{
			if (Occurrences(source, item.Start) != 1 || Occurrences(source, item.End) != 1)
			{
				throw new InvalidOperationException("Support commander lexical scope changed: " + path);
			}
			int num = source.IndexOf(item.Start, StringComparison.Ordinal);
			int num2 = source.IndexOf(item.End, num, StringComparison.Ordinal) + item.End.Length;
			if (num2 < num + item.End.Length)
			{
				throw new InvalidOperationException("Support commander scope order changed: " + path);
			}
			string text = source.Substring(num, num2 - num);
			string text2 = "-- SCOM support commander scope " + item.Hash + " ";
			if (source.IndexOf(text2, StringComparison.Ordinal) >= 0)
			{
				if (Occurrences(source, text2 + Digest(text) + "\n") != 1)
				{
					throw new InvalidOperationException("Support commander applied scope drift: " + path);
				}
				continue;
			}
			Edit[] edits = item.Edits;
			foreach (Edit edit in edits)
			{
				if (Occurrences(text, edit.Old) != edit.Count)
				{
					throw new InvalidOperationException("Support commander edit anchor changed: " + path);
				}
				text = text.Replace(edit.Old, edit.New);
			}
			source = source.Substring(0, num) + text2 + Digest(text) + "\n" + text + source.Substring(num2);
		}
		return source;
	}
}
